app<-source('app.R')$value
checks<-0L
check<-function(x,label) {if(!isTRUE(x)) stop('FAIL: ',label,call.=FALSE);checks<<-checks+1L;cat('PASS:',label,'\n')}
fails<-function(expr) inherits(tryCatch(force(expr),error=identity),'error')
wait_run<-function(r,timeout=20) {worker<-pc_r_runner();on.exit(worker$cleanup());worker$start(r,timeout);deadline<-Sys.time()+timeout+5;repeat {Sys.sleep(.05);x<-worker$poll();if(!is.null(x)) return(x);if(Sys.time()>deadline) stop('Worker did not finish.')}}
tab<-pc_example('column')$table;s<-pc_defaults();original<-tab
r<-pc_r_record('Custom summary',pc_r_templates()$summary$code,'',tab,'Measurements')
z<-wait_run(r)
check(z$result$status=='success','custom R runs in a separate process and returns successfully')
check(identical(tab,original),'custom R leaves original source observations unchanged')
summary<-pc_read_text(z$result$tables[[1]]$data_tsv,'\t')
check(abs(as.numeric(summary$Mean[1])-mean(as.numeric(tab[[1]])))<1e-10,'custom summary agrees with independent R reference')
check(nzchar(z$result$svg) && startsWith(rawToChar(head(jsonlite::base64_dec(z$result$pdf),4)),'%PDF'),'custom ggplot returns SVG and vector PDF')
check(grepl("width='216.00pt'",z$result$svg,fixed=TRUE),'Advanced R figure export defaults to a three-inch canvas')
check(length(z$result$packages)>0 && any(vapply(z$result$packages,function(p) p$name=='ggplot2',logical(1))),'R/package versions are retained with results')
check(length(pc_r_records(list(z)))==1 && identical(z$source_tsv,pc_table_text(tab)),'record retains exact input and reviewable script')
p<-pc_project(tab,s,r_analyses=list(z));file<-'artifacts/tests/advanced-r-study.rdatacraft';pc_write_project(p,file);restored<-pc_load_project(file)
draft_file<-'artifacts/tests/advanced-r-draft.rdatacraft';pc_write_project(pc_project(tab,s,r_analyses=list(r)),draft_file)
check(is.null(pc_load_project(draft_file)$r_analyses[[1]]$result),'unexecuted drafts roundtrip with explicit null results')
check(p$schema_version==11 && length(restored$r_analyses)==1,'schema eleven saves and reopens Advanced R records')
check(identical(restored$r_analyses[[1]]$code,r$code) && identical(restored$r_analyses[[1]]$result$svg,z$result$svg),'scripts and vector figures survive roundtrip without execution')
check(pc_signature(tab,s)!=pc_signature(tab,s,r_analyses=list(z)),'saved analyses participate in unsaved-change tracking')
check(length(pc_decode_project(pc_project(tab,s))$r_analyses)==0,'older projects without Advanced R records remain supported')
custom<-pc_r_record('GLM outside presets',pc_r_templates()$glm$code,'stats',data.frame(Response=c(2,3,5,7,4,5,8,9,3,4,6,8),Treatment=rep(c('A','B'),each=6),Batch=rep(c('X','Y'),6)),'Count design')
glm_run<-wait_run(custom);coefs<-pc_read_text(glm_run$result$tables[[1]]$data_tsv,'\t')
ref<-coef(glm(Response~Treatment+Batch,data=pc_read_text(custom$source_tsv,'\t') |> transform(Response=as.numeric(Response)),family=poisson()))
check(glm_run$result$status=='success' && isTRUE(all.equal(as.numeric(coefs[[2]]),unname(ref),tolerance=1e-10)),'custom GLM beyond presets agrees with an independent model reference')
error<-wait_run(pc_r_record('Error','stop("Deliberate fixture error")','',tab,'Data'))
check(error$result$status=='error' && grepl('Deliberate fixture error',error$result$text),'worker errors return clear diagnostics without crashing the app')
logfile<-tempfile();writeBin(c(charToRaw(paste(rep('x',40000),collapse='')),as.raw(0)),logfile)
check(nchar(pc_r_log(logfile),type='bytes')==30000,'diagnostic reading is bounded even for a long single console line')
check(fails(pc_r_script('result <- (')),'invalid R syntax is rejected before execution')
missing<-r;missing$packages<-'RDataCraftMissingFixturePackage';worker<-pc_r_runner();check(fails(worker$start(missing)) && !worker$busy(),'missing packages do not trigger automatic installation')
slow<-r;slow$code<-'Sys.sleep(5);result<-list(text="late")';worker<-pc_r_runner();worker$start(slow,1);Sys.sleep(1.2);time<-worker$poll();check(time$result$status=='timeout' && !worker$busy(),'time limits stop the child process')
worker$start(slow);cancel<-worker$cancel();check(cancel$result$status=='cancelled' && !worker$busy(),'Stop cancels a running child and preserves the input snapshot')
check(fails(pc_r_svg('<svg xmlns="http://www.w3.org/2000/svg"><script>alert(1)</script></svg>')),'saved figures reject active SVG content')
for(style in c('fill:URL(https://example.invalid/image)','fill:u&#114;l(https://example.invalid/image)','fill:u\\72l(https://example.invalid/image)','@import "https://example.invalid/style"')) {
 check(fails(pc_r_svg(paste0('<svg xmlns="http://www.w3.org/2000/svg"><path style="',gsub('"','&quot;',style,fixed=TRUE),'"/></svg>'))),'saved SVG rejects external, encoded and escaped CSS references')
}
check(!fails(pc_r_svg('<svg xmlns="http://www.w3.org/2000/svg"><defs><clipPath id="clip-1"/></defs><path clip-path="url(#clip-1)"/></svg>')),'saved SVG retains local clipping references')
check(fails(pc_r_svg('<svg xmlns="http://www.w3.org/2000/svg"><set attributeName="href" to="https://example.invalid/"/></svg>')),'saved SVG rejects attribute-changing animation')
bad<-z;bad$result$tables[[1]]$data_tsv<-'A\tB\n1';check(fails(pc_r_records(list(bad))),'corrupt stored output tables reject on project loading')
marker<-normalizePath('artifacts',mustWork=TRUE);marker<-file.path(marker,'custom-ai-not-executed.txt');unlink(marker)
code<-paste0('writeLines("unexpected",',dQuote(marker,q=FALSE),');result<-list(text="draft")')
op<-list(type='r_analysis',title='AI custom draft',parameters=list(list(key='code',value=code),list(key='packages',value='stats')))
plan<-pc_ai_prepare(tab,s,'Data',list(answer='Review this draft.',operations=list(op)))
check(!file.exists(marker) && identical(plan$r_draft$code,code),'AI drafting validates code without executing it')
check(fails(pc_ai_prepare(tab,s,'Data',list(answer='Mixed',operations=list(op,list(type='graph',title='Plot',parameters=list()))))),'custom R drafts cannot mix with automatically rendered operations')
check(all(c('r_analysis','analysis') %in% pc_ai_schema()$properties$operations$items$properties$type$enum),'assistant schema supports explicit Advanced R drafts')
check(all(pc_p_value(c(0,1e-7,1e-6,.000045,.034567,NA))==c('< 10⁻⁶','< 10⁻⁶','0.000001','0.000045','0.03457','—')),'numeric P values retain four significant digits above the one-millionth threshold')
check(identical(pc_p_label(c(1e-7,.00004)),c('p < 10⁻⁶','p = 0.00004')),'graph labels use the new numeric threshold consistently')
formatted<-pc_graph_edit(tab,s,list(annotation='stars'))
check(pc_decode_project(pc_project(tab,formatted))$settings$annotation=='stars','P display choices work through direct graph formatting and saved studies')
check(identical(pc_p_label(c(.2,.05,.01,.001,.0001),stars=TRUE),c('ns','*','**','***','****')),'significance stars preserve documented boundary cutoffs')
shiny::testServer(app,{
 raw(tab);document_open(TRUE);project_name('R test');do.call(session$setInputs,s);session$flushReact()
 before<-raw();session$setInputs(r_title='Draft fixture',r_code='result<-list(text="saved draft")',r_packages='',r_save_draft=1);session$flushReact()
 check(length(r_analyses())==1 && is.null(r_analyses()[[1]]$result) && identical(raw(),before),'saving a server draft records its input without running or altering data')
 session$setInputs(r_saved='1',r_load_saved=1);session$flushReact();check(!advanced$busy(),'loading a stored script never starts the R runner')
 restore_project(pc_decode_project(pc_project(tab,s,r_analyses=list(z))),'Reloaded');session$flushReact();check(length(r_analyses())==1 && !advanced$busy(),'project restoration restores results without executing code')
 # Server side AI draft delivery also requires an explicit Run click.
 session$setInputs(assistant_prompt='Draft custom analysis',assistant_send=1);session$flushReact();req<-assistant$pending()
 session$setInputs(assistant_response=list(id=req$id,ok=TRUE,response=jsonlite::toJSON(list(answer='Draft',operations=list(op)),auto_unbox=TRUE)));session$flushReact()
 session$setInputs(assistant_apply=1);session$flushReact()
 check(page()=='advanced' && !advanced$busy() && !file.exists(marker),'Open in Advanced R routes an AI draft to review without execution')
 r_analyses(lapply(1:19,function(i) {x<-r;x$id<-paste0('slot-',i);x}))
 session$setInputs(r_title='Concurrent result',r_code='Sys.sleep(20);result<-list(text="completed")',r_packages='',r_use_saved=FALSE,r_timeout=30,r_run=1);session$flushReact()
 session$setInputs(r_save_draft=2);session$flushReact()
 check(length(r_analyses())==19 && advanced$busy(),'draft saves during execution cannot consume the reserved result slot')
 session$setInputs(r_stop=1);session$flushReact()
 check(length(r_analyses())==20 && !advanced$busy() && tail(r_analyses(),1)[[1]]$result$status=='cancelled','the completed or stopped run retains its input and result at the record limit')
})
cat(checks,'Advanced R and P-label checks passed.\n')
